using System.Collections;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DevourAction", menuName = "Data/Battle/Battle Actions/Enemy/Devour Action")]
public class DevourAction : BattleAction
{
	[Header("Devour")]
	[SerializeField]
	private CorruptAction corruptAction;

	[SerializeField]
	private int devourIncreaseAmount;

	[Header("VFX")]
	[SerializeField]
	private float VFXDelay;

	public CorruptAction CorruptAction => corruptAction;

	public int DevourIncreaseAmount => devourIncreaseAmount;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueBeforeMainActionAction(VFXCoroutine(target, amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			DefaultCast(target, amount, source);
		}
	}

	private IEnumerator VFXCoroutine(GameObject target, int amount, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(source), 4f);
		yield return new WaitForSeconds(VFXDelay);
		SpawnSecondVFXOnPlayerPosition(4f);
		DefaultCast(target, amount, source);
	}

	private void DefaultCast(GameObject target, int amount, GameObject source)
	{
		corruptAction.CastTargetAmount(target, amount, source);
		int actionAmount = amount + devourIncreaseAmount;
		OverCorruptionAction overCorruptionAction = new OverCorruptionAction(this, actionAmount);
		source.GetComponent<CorruptedAnimalCorruptionStats>().CorruptedAnimalOverCorruption.Initialize(overCorruptionAction);
	}
}
